-- Read-only, run by the agent: plan and result of the per-family content_md_type_* SQL of
-- reports/wikipedia-content-md-backfill.yaml, before the nightly run picks them up. The EXISTS
-- probe must use the link table's unique key (ref on ID_WIKIDATA, LANG), not a scan of every link.

EXPLAIN SELECT COUNT(*) FROM T_WC_WIKIPEDIA_PAGE_LANG p JOIN (SELECT DISTINCT ID_WIKIDATA FROM T_WC_TMDB_PERSON WHERE ID_WIKIDATA REGEXP '^Q[0-9]+$') s ON s.ID_WIKIDATA = p.ID_WIKIDATA WHERE p.PAGE_EXISTS = 1 AND EXISTS (SELECT 1 FROM T_WC_WIKIPEDIA_PAGE_LANG_LINK l WHERE l.ID_WIKIDATA = p.ID_WIKIDATA AND l.LANG = p.LANG);
EXPLAIN SELECT COUNT(*) FROM T_WC_WIKIPEDIA_PAGE_LANG p JOIN (SELECT DISTINCT ID_WIKIDATA FROM T_WC_WIKIDATA_ITEM_V1 WHERE ID_WIKIDATA REGEXP '^Q[0-9]+$') s ON s.ID_WIKIDATA = p.ID_WIKIDATA WHERE p.PAGE_EXISTS = 1 AND EXISTS (SELECT 1 FROM T_WC_WIKIPEDIA_PAGE_LANG_LINK l WHERE l.ID_WIKIDATA = p.ID_WIKIDATA AND l.LANG = p.LANG);

SELECT 'content_md_type_movie' AS METRIC,
  (SELECT COUNT(*) FROM T_WC_WIKIPEDIA_PAGE_LANG p JOIN (SELECT DISTINCT ID_WIKIDATA FROM T_WC_TMDB_MOVIE WHERE ID_WIKIDATA REGEXP '^Q[0-9]+$') s ON s.ID_WIKIDATA = p.ID_WIKIDATA WHERE p.PAGE_EXISTS = 1 AND EXISTS (SELECT 1 FROM T_WC_WIKIPEDIA_PAGE_LANG_LINK l WHERE l.ID_WIKIDATA = p.ID_WIKIDATA AND l.LANG = p.LANG)) AS DONE,
  (SELECT COUNT(*) FROM T_WC_WIKIPEDIA_PAGE_LANG p JOIN (SELECT DISTINCT ID_WIKIDATA FROM T_WC_TMDB_MOVIE WHERE ID_WIKIDATA REGEXP '^Q[0-9]+$') s ON s.ID_WIKIDATA = p.ID_WIKIDATA WHERE p.PAGE_EXISTS = 1) AS EXPECTED
UNION ALL SELECT 'content_md_type_serie',
