  (SELECT COUNT(*) FROM T_WC_WIKIPEDIA_PAGE_LANG p JOIN (SELECT DISTINCT ID_WIKIDATA FROM T_WC_TMDB_SERIE WHERE ID_WIKIDATA REGEXP '^Q[0-9]+$') s ON s.ID_WIKIDATA = p.ID_WIKIDATA WHERE p.PAGE_EXISTS = 1)
UNION ALL SELECT 'content_md_type_season',
